write('shared/fastify-lab.mjs', '''
export async function inspectApp(app, check){try{await app.ready();await check();if(process.argv.includes('--serve')){await app.listen({port:Number(process.env.PORT??3000),host:'127.0.0.1'});console.log('Listening on',app.server.address());await new Promise(resolve=>{process.once('SIGINT',resolve);process.once('SIGTERM',resolve);});}}finally{await app.close();}}
''')
add(68,'''import {assert,spawnNode} from '../../shared/lab.mjs';const r=await spawnNode(['lifecycle.mjs']);console.log(r.stdout);assert.equal(r.code,0);assert.equal(r.stdout.trim().split('\\n').filter(x=>x==='cleaned up').length,1);''','A finite harness calls idempotent shutdown twice but cleans up only once.',files={'lifecycle.mjs':"let closing=false;const timer=setInterval(()=>console.log('working'),1000);function shutdown(){if(closing)return;closing=true;clearInterval(timer);console.log('cleaned up');}process.on('SIGINT',shutdown);process.on('SIGTERM',shutdown);if(!process.argv.includes('--interactive'))setTimeout(()=>{shutdown();shutdown();},20);"})
add(69,'''import {assert,spawnNode} from '../../shared/lab.mjs';const payload='hello; & echo data';const r=await spawnNode(['helper.mjs',payload],{timeout:1000});console.log(r);assert.equal(r.code,0);assert.equal(r.stdout.trim(),payload);''','Shell-looking input is printed literally by a child process using an argument array, never interpolated.',files={'helper.mjs':'console.log(process.argv[2]);'})
add(70,'''import {fork} from 'node:child_process';import assert from 'node:assert/strict';const child=fork(new URL('./child.mjs',import.meta.url),{stdio:['ignore','inherit','inherit','ipc']});const pending=new Map();child.on('message',m=>{const item=pending.get(m.id);if(item){clearTimeout(item.timer);pending.delete(m.id);item.resolve(m.value);}});child.on('exit',()=>{for(const item of pending.values()){clearTimeout(item.timer);item.reject(Error('Child exited'));}pending.clear();});let id=0;function rpc(type,value){return new Promise((resolve,reject)=>{const key=String(++id),timer=setTimeout(()=>{pending.delete(key);reject(Error('Deadline'));},80);pending.set(key,{resolve,reject,timer});child.send({id:key,type,value});});}try{console.log(await rpc('double',21));await assert.rejects(rpc('ignore',0),/Deadline/);console.log('missing reply deadline cleaned:',pending.size);}finally{child.disconnect();await new Promise(r=>child.once('exit',r));}''','Request IDs correlate replies; a missing reply times out and removes its pending entry.',files={'child.mjs':"process.on('message',message=>{if(message.type==='double')process.send?.({id:message.id,value:message.value*2});});"})
add(71,'''import {Worker} from 'node:worker_threads';import assert from 'node:assert/strict';const worker=new Worker(new URL('./worker.mjs',import.meta.url),{workerData:100000});const answer=await new Promise((resolve,reject)=>{worker.once('message',resolve);worker.once('error',reject);});console.log(answer);assert.equal(answer,5000050000);await new Promise((resolve,reject)=>worker.once('exit',code=>code?reject(Error('Worker failed')):resolve()));''','The worker computes 5000050000 on its own JavaScript thread and exits naturally.',files={'worker.mjs':"import {parentPort,workerData} from 'node:worker_threads';let total=0;for(let i=1;i<=workerData;i++)total+=i;parentPort.postMessage(total);"})
add(72,'''import Piscina from 'piscina';import assert from 'node:assert/strict';const pool=new Piscina({filename:new URL('./worker.mjs',import.meta.url).href,minThreads:2,maxThreads:2,maxQueue:4});try{assert.equal(await pool.run(100000),5000050000);const outcomes=await Promise.allSettled(Array.from({length:12},()=>pool.run(1000000)));console.log({fulfilled:outcomes.filter(x=>x.status==='fulfilled').length,rejected:outcomes.filter(x=>x.status==='rejected').length});assert.ok(outcomes.some(x=>x.status==='rejected'));}finally{await pool.destroy();}''','A bounded two-thread pool computes a result and rejects excess queued work.',files={'worker.mjs':"export default n=>{let total=0;for(let i=1;i<=n;i++)total+=i;return total;};"},deps=['piscina'])
add(73,'''import {MessageChannel} from 'node:worker_threads';import assert from 'node:assert/strict';const {port1,port2}=new MessageChannel(),buffer=new ArrayBuffer(1024*1024);const received=new Promise(r=>port2.once('message',r));port1.postMessage(buffer,[buffer]);console.log('sender:',buffer.byteLength);assert.equal(buffer.byteLength,0);const value=await received;console.log('received:',value.byteLength);assert.equal(value.byteLength,1048576);port1.close();port2.close();''','Transfer detaches the sender ArrayBuffer while the receiver owns the original-sized storage.')
add(74,'''import {Worker} from 'node:worker_threads';import assert from 'node:assert/strict';const shared=new SharedArrayBuffer(Int32Array.BYTES_PER_ELEMENT);await Promise.all([1,2].map(()=>new Promise((resolve,reject)=>{const worker=new Worker(new URL('./worker.mjs',import.meta.url),{workerData:shared});worker.on('error',reject);worker.on('exit',code=>code?reject(Error('Worker failed')):resolve());})));console.log(Atomics.load(new Int32Array(shared),0));assert.equal(Atomics.load(new Int32Array(shared),0),200000);''','Two workers update one shared counter without a read-modify-write race.',files={'worker.mjs':"import {workerData} from 'node:worker_threads';const view=new Int32Array(workerData);for(let i=0;i<100000;i++)Atomics.add(view,0,1);"})
add(75,'''import cluster from 'node:cluster';import {createServer} from 'node:http';import assert from 'node:assert/strict';if(cluster.isPrimary){let stopping=false,restarts=0;const ready=[];function fork(){const w=cluster.fork();w.on('message',m=>{if(m.port)ready.push(m);});return w;}fork();fork();cluster.on('exit',()=>{if(!stopping&&restarts++<1)fork();});try{const deadline=Date.now()+5000;while(ready.length<2){if(Date.now()>deadline)throw Error('Workers did not start');await new Promise(r=>setTimeout(r,10));}const pids=new Set();for(let i=0;i<8;i++){const r=await fetch('http://127.0.0.1:'+ready[0].port);pids.add(await r.text());}console.log('Observed PIDs:',[...pids],'workers:',Object.keys(cluster.workers).length);assert.equal(Object.keys(cluster.workers).length,2);}finally{stopping=true;await Promise.all(Object.values(cluster.workers).map(w=>new Promise(resolve=>{w.once('exit',resolve);w.send('shutdown');})));}}else{const server=createServer((q,s)=>s.end(String(process.pid)));server.listen(0,'127.0.0.1',()=>process.send({port:server.address().port,pid:process.pid}));process.on('message',m=>{if(m==='shutdown')server.close(()=>process.disconnect());});}''','Two separate processes serve a shared listening endpoint. Observed PID distribution is not required to alternate. Shutdown prevents respawn loops.')
add(76,'''import Fastify from 'fastify';import assert from 'node:assert/strict';import {inspectApp} from '../../shared/fastify-lab.mjs';const app=Fastify();const phases=[];app.addHook('onRequest',async()=>{phases.push('onRequest');});app.setErrorHandler((error,q,r)=>r.code(500).send({error:'Internal error'}));app.get('/tasks',async()=>[{id:1,title:'Learn Node.js'}]);app.get('/fail',async()=>{throw Error('private fixture detail');});await inspectApp(app,async()=>{for(const [url,status] of [['/tasks',200],['/missing',404],['/fail',500]]){const r=await app.inject(url);console.log(url,r.statusCode,r.body);assert.equal(r.statusCode,status);}assert.equal(phases.length,3);});''','Fastify lifecycle hooks run; thrown async errors become sanitized 500 responses. Add --serve to inspect endpoints manually.',deps=['fastify'])
add(77,'''import express from 'express';import {createServer} from 'node:http';import {assert,listen,close} from '../../shared/lab.mjs';const app=express(),order=[];app.use((q,r,next)=>{order.push('before');next();});app.get('/tasks',(q,r)=>r.json([]));app.get('/fail',async()=>{throw Error('fixture');});app.use((e,q,r,next)=>{if(r.headersSent)return next(e);order.push('error');r.status(500).json({error:'Internal error'});});const server=createServer(app),base=await listen(server);try{for(const [path,status] of [['/tasks',200],['/fail',500],['/missing',404]]){const r=await fetch(base+path);console.log(path,r.status,await r.text());assert.equal(r.status,status);}console.log(order);}finally{await close(server);}''','Express 5 forwards rejected route promises to the four-argument error middleware; unknown routes remain 404.',deps=['express'])
add(78,'''import Fastify from 'fastify';import assert from 'node:assert/strict';import {inspectApp} from '../../shared/fastify-lab.mjs';const app=Fastify();app.post('/tasks/:id',{schema:{params:{type:'object',required:['id'],properties:{id:{type:'integer'}}},body:{type:'object',required:['title'],properties:{title:{type:'string',minLength:1}}},response:{201:{type:'object',additionalProperties:false,properties:{id:{type:'integer'},title:{type:'string'}}}}}},async(q,r)=>r.code(201).send({id:q.params.id,title:q.body.title,internal:'hidden'}));await inspectApp(app,async()=>{for(const [url,payload,status] of [['/tasks/1',{title:'hello'},201],['/tasks/x',{title:'hello'},400],['/tasks/1',{},400]]){const r=await app.inject({method:'POST',url,payload});console.log(r.statusCode,r.body);assert.equal(r.statusCode,status);if(status===201)assert.ok(!('internal'in r.json()));}});''','Invalid input yields 400, while the response schema strips an internal field from the successful 201 response.',deps=['fastify'])
add(79,'''import Fastify from 'fastify';import assert from 'node:assert/strict';import {inspectApp} from '../../shared/fastify-lab.mjs';const app=Fastify(),tasks=Array.from({length:5},(_,i)=>({id:i+1,title:'Task '+(i+1)}));app.get('/tasks',async(q,r)=>{const after=Number(q.query.after??0),limit=Number(q.query.limit??2);if(!Number.isSafeInteger(after)||after<0||!Number.isInteger(limit)||limit<1||limit>100)return r.code(400).send({error:'Invalid cursor or limit'});const items=tasks.filter(x=>x.id>after).slice(0,limit);return{items,next:items.length?items.at(-1).id:null};});await inspectApp(app,async()=>{let after=0,ids=[];while(true){const r=(await app.inject('/tasks?after='+after)).json();console.log(r);if(!r.items.length)break;ids.push(...r.items.map(x=>x.id));after=r.next;}assert.deepEqual(ids,[1,2,3,4,5]);assert.equal((await app.inject('/tasks?limit=1000')).statusCode,400);});''','Cursor traversal returns each fixture ID exactly once and rejects unbounded limits.',deps=['fastify'])
add(80,'''import Fastify from 'fastify';import swagger from '@fastify/swagger';import assert from 'node:assert/strict';const app=Fastify();try{await app.register(swagger,{openapi:{info:{title:'Tasks API',version:'1.0.0'}}});app.get('/health',{schema:{response:{200:{type:'object',properties:{ok:{type:'boolean'}}}}}},async()=>({ok:true}));await app.ready();const doc=app.swagger();console.log(JSON.stringify(doc,null,2));assert.equal(doc.info.title,'Tasks API');assert.ok(doc.paths['/health']);assert.equal((await app.inject('/health')).json().ok,true);}finally{await app.close();}''','The generated OpenAPI document contains the real route and agrees with its response contract.',deps=['fastify','@fastify/swagger'])
write('shared/upload.mjs', '''
import Fastify from 'fastify';import multipart from '@fastify/multipart';import {pipeline} from 'node:stream/promises';import {createWriteStream} from 'node:fs';import {rm,mkdir} from 'node:fs/promises';import {join} from 'node:path';import {randomUUID} from 'node:crypto';
export async function uploadApp(directory){const app=Fastify();await mkdir(directory,{recursive:true});await app.register(multipart,{limits:{fileSize:1024,files:1,parts:2}});app.post('/upload',async(q,r)=>{const part=await q.file();if(!part)return r.code(400).send({error:'File required'});const target=join(directory,randomUUID());try{await pipeline(part.file,createWriteStream(target,{flags:'wx'}));if(part.file.truncated){await rm(target,{force:true});return r.code(413).send({error:'Too large'});}return{stored:true};}catch(error){await rm(target,{force:true});throw error;}});return app;}
''')
add(81,'''import {uploadApp} from '../../shared/upload.mjs';import {assert,fs,temp} from '../../shared/lab.mjs';await using lab=await temp();const app=await uploadApp(lab.path);try{await app.listen({port:0,host:'127.0.0.1'});for(const [size,status] of [[5,200],[2048,413]]){const form=new FormData();form.append('file',new Blob(['x'.repeat(size)]),'unsafe-client-name.txt');const response=await fetch('http://127.0.0.1:'+app.server.address().port+'/upload',{method:'POST',body:form});console.log({size,status:response.status,body:await response.text()});assert.equal(response.status,status);}assert.equal((await fs.readdir(lab.path)).length,1);console.log('only complete upload retained with generated filename');}finally{await app.close();}''','A real multipart client uploads a small file; an oversized stream yields 413 and removes its partial output.',deps=['fastify','@fastify/multipart'])
add(82,'''import {WebSocketServer} from 'ws';import assert from 'node:assert/strict';const server=new WebSocketServer({port:0,host:'127.0.0.1',maxPayload:1024});const timer=setInterval(()=>{for(const client of server.clients){if(client.isAlive===false){client.terminate();continue;}client.isAlive=false;client.ping();}},1000);server.on('connection',socket=>{socket.isAlive=true;socket.on('pong',()=>socket.isAlive=true);socket.on('error',()=>{});socket.on('message',data=>{try{const value=JSON.parse(data);if(typeof value.text!=='string')return socket.close(1008,'Invalid message');if(socket.bufferedAmount>65536)return socket.close(1013,'Slow client');socket.send(JSON.stringify(value));}catch{socket.close(1008,'Invalid JSON');}});});await new Promise(r=>server.once('listening',r));const client=new WebSocket('ws://127.0.0.1:'+server.address().port);try{await new Promise((resolve,reject)=>{client.addEventListener('open',resolve,{once:true});client.addEventListener('error',reject,{once:true});});const received=new Promise(r=>client.addEventListener('message',e=>r(e.data),{once:true}));client.send(JSON.stringify({text:'hello'}));const data=await received;console.log(data);assert.equal(JSON.parse(data).text,'hello');}finally{client.close();await new Promise(r=>client.addEventListener('close',r,{once:true}));clearInterval(timer);await new Promise(r=>server.close(r));}''','A native WebSocket client exchanges validated JSON with the external ws server; heartbeat and listener resources are cleaned up.',deps=['ws'])
add(83,'''import {createServer} from 'node:http';import {assert,listen,close,delay} from '../../shared/lab.mjs';let active=0;const history=[{id:1,data:{ok:true}},{id:2,data:{step:'done'}}];const server=createServer((q,s)=>{s.writeHead(200,{'content-type':'text/event-stream','cache-control':'no-cache'});active++;const last=Number(q.headers['last-event-id']??0);for(const event of history.filter(x=>x.id>last))s.write(`id: ${event.id}\\nevent: ready\\ndata: ${JSON.stringify(event.data)}\\n\\n`);const heartbeat=setInterval(()=>s.write(': heartbeat\\n\\n'),50);s.once('close',()=>{clearInterval(heartbeat);active--;});});const base=await listen(server);try{const response=await fetch(base,{headers:{'Last-Event-ID':'1'}});const reader=response.body.getReader();const {value}=await reader.read();const text=new TextDecoder().decode(value);console.log(text);assert.ok(text.includes('id: 2'));assert.ok(!text.includes('id: 1'));await reader.cancel();for(let i=0;active&&i<100;i++)await delay(5);assert.equal(active,0);}finally{await close(server);}''','Reconnection replays only events after Last-Event-ID; disconnect clears heartbeat state.')
add(84,'''import Fastify from 'fastify';import cors from '@fastify/cors';import assert from 'node:assert/strict';import {inspectApp} from '../../shared/fastify-lab.mjs';const app=Fastify();await app.register(cors,{origin:'http://localhost:5173',credentials:true});app.get('/data',async()=>({ok:true}));await inspectApp(app,async()=>{for(const origin of ['http://localhost:5173','http://untrusted.invalid']){const r=await app.inject({url:'/data',headers:{origin}});console.log({origin,status:r.statusCode,allow:r.headers['access-control-allow-origin']});assert.equal(r.statusCode,200);assert.equal(r.headers['access-control-allow-origin'],'http://localhost:5173');}console.log('CORS headers grant the configured origin; they do not authenticate requests.');});''','The API emits its configured allow-origin value. A browser on a different origin cannot read the response even though the HTTP request can succeed.','Run --serve for the API, then run node browser.mjs in another terminal and open http://localhost:5173. The browser page demonstrates the actual browser-enforced policy.',files={'public/index.html':'<!doctype html><title>CORS client</title><button id="load">Fetch API</button><pre id="output"></pre><script>document.querySelector("#load").onclick=async()=>{try{const r=await fetch("http://localhost:3000/data",{credentials:"include"});document.querySelector("#output").textContent=await r.text();}catch(e){document.querySelector("#output").textContent=e.message;}};</script>','browser.mjs':"import {createServer} from 'node:http';import {readFile} from 'node:fs/promises';const html=await readFile(new URL('./public/index.html',import.meta.url));createServer((q,s)=>{s.setHeader('content-type','text/html');s.end(html);}).listen(5173,'127.0.0.1');"},deps=['fastify','@fastify/cors'])
